return items.map(item => {
  // Validar que existe el contenido
  if (!item.json.message || !item.json.message.content) {
    return item;
  }

  let content = item.json.message.content;

  // Remover markdown code blocks
  content = content.replace(/^```html\n/, '').replace(/```$/, '').trim();

  // Remover el H1 (con su contenido y etiquetas de apertura/cierre)
  content = content.replace(/<h1>.*?<\/h1>\s*/s, '');

  return {
    json: {
      ...item.json,
      message: {
        ...item.json.message,
        content: content
      }
    }
  };
});
